"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51919"],{79542(e){e.exports=JSON.parse('{"id":"F453","slug":"j-curve-cumulative-cash","name":"J-Curve: Cumulative Net Cash Flow of a Fund","subject":"Alternative Investments","section":"Alternatives","topic":"J-curve and fund structures (GP/LP, carried interest)","level":"Beginner","aliases":["J-curve","capital calls and distributions","fund trough","breakeven year"],"formula":{"latex":"C_{t}=\\\\sum_{k\\\\le t}(D_{k}-P_{k}),\\\\quad \\\\text{Trough}=\\\\min_{t}C_{t}","also":[],"text":"Net cash flow in year t = distributions - capital called; Cumulative net cash = running total; The trough (lowest point) is the most capital an investor has out at once; Breakeven year = first year the running total is zero or more"},"symbols":[{"symbol":"P_t","meaning":"Capital called from the investor in year t (drawdown, including fees)","unit":"money"},{"symbol":"D_t","meaning":"Cash returned to the investor in year t","unit":"money"},{"symbol":"C_t","meaning":"Running total of net cash flow","unit":"money"}],"when_to_use":"Use it to see the J-curve of a private fund. In early years fees and unrealized investments push the net position below zero; later sales bring it back and above. The trough shows the cash an investor must be ready to fund, and the breakeven year shows the wait. Carry paid to the manager (the GP) comes out of distributions, which are already net here.","worked_example":{"problem":"A fund calls 20, 25, 25, 15 and 5 in years 1 to 5, and pays back 0, 0, 5, 10, 20, 30, 35, 30, 20 and 10 in years 1 to 10 (all per 100 committed).","inputs":{"p":[20,25,25,15,5,0,0,0,0,0],"d":[0,0,5,10,20,30,35,30,20,10]},"steps":[{"label":"Net cash flow per year","working":null,"value":"-20.00, -25.00, -20.00, -5.00, 15.00, 30.00, 35.00, 30.00, 20.00, 10.00"},{"label":"Cumulative net cash","working":null,"value":"-20.00, -45.00, -65.00, -70.00, -55.00, -25.00, 10.00, 40.00, 60.00, 70.00"},{"label":"Trough (lowest cumulative point)","working":"min([-20, -45, -65, -70, -55, -25, 10, 40, 60, 70])","value":"-70.00"},{"label":"Total capital called","working":null,"value":"90.00"},{"label":"Total distributions","working":null,"value":"160.00"},{"label":"Net gain","working":"160-90","value":"70.00"},{"label":"Year of the trough","working":null,"value":"4"},{"label":"Breakeven year (first year at or above zero after the trough)","working":null,"value":"7"}],"answer":"The cumulative net cash flow bottoms at -70.00, so up to 90.00 of the 100 commitment was called. The fund returns 160.00 in total, a net gain of 70.00. The running total first reaches zero or more in year 7."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Capital called per year","unit":"money","type":"list","default":[20,25,25,15,5,0,0,0,0,0],"hint":""},{"id":"d","label":"Distributions per year","unit":"money","type":"list","default":[0,0,5,10,20,30,35,30,20,10],"hint":""}],"checks":[{"expr":"count(p)==count(d) and count(p)>=3","message":"Enter the same number of years for calls and distributions."}],"steps":[{"id":"net","label":"Net cash flow per year","expr":"minus(d, p)","format":"list2"},{"id":"cs","label":"Cumulative net cash","expr":"cumsum(net)","format":"list2"},{"id":"trough","label":"Trough (lowest cumulative point)","expr":"min(cs)","format":"num2"},{"id":"paid","label":"Total capital called","expr":"sum(p)","format":"num2"},{"id":"tot","label":"Total distributions","expr":"sum(d)","format":"num2"},{"id":"gain","label":"Net gain","expr":"tot-paid","format":"num2"},{"id":"tpos","label":"Year of the trough","expr":"argmin(cs)","format":"num0"},{"id":"be","label":"Breakeven year (first year at or above zero after the trough)","expr":"firstidx(cs, 0, tpos)","format":"num0"}],"results":["trough","tpos","be","gain"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"trough":-70,"paid":90,"tot":160,"gain":70,"tpos":4,"be":7}},"finder":{"finds":"Depth and length of the J-curve","needs":"Capital called and distributions by year"},"related":[{"slug":"fund-performance-metrics","name":"Private Fund Metrics: IRR, MOIC, TVPI, DPI, RVPI"},{"slug":"pe-carry-waterfall","name":"Private Equity Distribution Waterfall and Carry"},{"slug":"payback-period","name":"Payback Period"}],"related_ids":["F454","F370","F154"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>C</mi><mi>t</mi></msub><mo>=</mo><munder><mo>\u2211</mo><mrow><mi>k</mi><mo>\u2264</mo><mi>t</mi></mrow></munder><mo stretchy=\\"false\\">(</mo><msub><mi>D</mi><mi>k</mi></msub><mo>\u2212</mo><msub><mi>P</mi><mi>k</mi></msub><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Trough</mtext><mo>=</mo><munder><mrow><mi>min</mi><mo>\u2061</mo></mrow><mi>t</mi></munder><msub><mi>C</mi><mi>t</mi></msub></mrow><annotation encoding=\\"application/x-tex\\">C_{t}=\\\\sum_{k\\\\le t}(D_{k}-P_{k}),\\\\quad \\\\text{Trough}=\\\\min_{t}C_{t}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"ito-lemma-drift","name":"It\xf4\'s Lemma: Drift and Volatility of a Function"},"next":{"slug":"jensens-alpha","name":"Jensen\'s Alpha"},"lesson":null,"total":522}')}}]);